      kQWhyNot: "Why not this one",
      kQScore: "You got {n} out of {m}",
      kQm1: "A good start! Every answer you read taught you something. Try another round.",
      kQm2: "Nice work! You already read the Moon like a mission planner. One more round?",
      kQm3: "Excellent! Only one slip. You could plan a landing.",
      kQm4: "Perfect score! You are ready to choose a landing day for a real mission.",
      kQAgain: "Play again",
      kQpass: "passes",
      kQfail: "fails",
      kQnDays: "{n} days",
      kQfAll: "The grid says {verdict} for this day. Longest night {night} days (limit {nl}), longest radio silence {radio} days (limit {rl}), Sun on the first day: {sun}.",
      kQfNight: "Longest night: {night} days. The battery carries {nl} days, so this check {res}.",
      kQfRadio: "Longest radio silence: {radio} days. The limit is {rl} days, so this check {res}.",
      kQfSun: "Sun on the first day: {sun}. It must be up at landing or rise within 24 hours, so this check {res}.",
      kQfSlope: "Ground slope: {slope} degrees. It must be under 10 degrees, so this check {res}.",
      kQfWin: "{site}: survives. Longest night {night} days (limit {nl}), longest radio silence {radio} days (limit {rl}), Sun on the first day: {sun}.",
      kQfLose: "{site}: lost. {why}",
      kQfSunPct: "{site}: the Sun is up for {p}% of the 14 days.",
      kQfEarthPct: "{site}: Earth is in view for {p}% of the 14 days.",
